package com.bank.partitions;

import java.util.*;
import java.util.logging.*;

public class PartitionSizingDemo {
    private static final Logger log = Logger.getLogger(PartitionSizingDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PartitionPlanner planner = new PartitionPlanner();

        // Sizing: target 60 MB/s, each partition sustains 10 MB/s, 2x headroom.
        int recommended = planner.recommendPartitions(60, 10, 2);
        log.info(() -> "Recommended partition count: " + recommended);

        // Show why you cannot shrink: the SAME key maps to a DIFFERENT
        // partition when the count changes, breaking per-key ordering.
        String[] accounts = {"SAV2001", "CUR3001"};  // Rajesh, Priya
        for (String account : accounts) {
            int at12 = planner.partitionForKey(account, 12);
            int at6  = planner.partitionForKey(account, 6);
            log.info(() -> account + " → partition " + at12 + " (with 12) but "
                    + at6 + " (with 6) — shrinking reshuffles keys!");
        }

        // Guard against the illegal shrink.
        try {
            planner.validateRepartition(12, 6);
        } catch (IllegalArgumentException e) {
            log.severe("Rejected repartition: " + e.getMessage());
        }
    }
}

// ─── Would be in service/PartitionPlanner.java in a real project ───
class PartitionPlanner {

    // throughput-based sizing with growth headroom
    int recommendPartitions(int targetMbPerSec, int perPartitionMbPerSec, int headroomFactor) {
        if (perPartitionMbPerSec <= 0) throw new IllegalArgumentException("per-partition must be > 0");
        int floor = (int) Math.ceil((double) targetMbPerSec / perPartitionMbPerSec);
        return floor * headroomFactor;
    }

    // mirrors Kafka's default key→partition mapping: hash(key) mod partitions
    int partitionForKey(String key, int partitionCount) {
        int hash = Objects.hashCode(key) & 0x7fffffff;  // non-negative
        return hash % partitionCount;
    }

    // enforce the "never decrease" rule
    void validateRepartition(int current, int target) {
        if (target < current) {
            throw new IllegalArgumentException(
                "Cannot decrease partitions from " + current + " to " + target
                + ": would strand data and break key-based ordering");
        }
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
